# 6-turkce-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">3. TEMA: FARKLI DÜNYALAR — "OVA ÇOCUK" VE "MISIR-İSPANYA-NORVEÇ" KARŞILAŞTIRMASI</text>\n  <rect x="20" y="50" width="210" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Mısır (Kuzey Afrika / Çöl)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11" fill="#334155">• Nil Nehri ve sıcak iklim</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#334155">• Piramitler ve kadim tarih</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#334155">• Sıcakkanlı selamlaşma ve</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#334155">misafirperver sofra kültürü</text>\n  <rect x="245" y="50" width="210" height="175" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">İspanya (Güney Avrupa / Akdeniz)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#334155">• Akdeniz iklimi ve neşeli yaşam</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#334155">• Endülüs mimari mirası</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#334155">• Meydan kültürü, sanat ve</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">canlı beden dili kullanımı</text>\n  <rect x="470" y="50" width="210" height="175" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Norveç (Kuzey Avrupa / Kutup)</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11" fill="#334155">• Fiyortlar, kar ve kuzey ışıkları</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#334155">• Gece yarısı güneşi / kış gecesi</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11" fill="#334155">• Doğa sporları, sakin iletişim</text>\n  <text x="575" y="160" text-anchor="middle" font-size="11" fill="#334155">ve kişisel alana saygı</text>\n</svg>', '1': '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">3. TEMA: FARKLI DÜNYALAR — "OVA ÇOCUK" VE "MISIR-İSPANYA-NORVEÇ" KARŞILAŞTIRMASI</text>\n  <rect x="20" y="50" width="210" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Mısır (Kuzey Afrika / Çöl)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11" fill="#334155">• Nil Nehri ve sıcak iklim</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#334155">• Piramitler ve kadim tarih</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#334155">• Sıcakkanlı selamlaşma ve</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#334155">misafirperver sofra kültürü</text>\n  <rect x="245" y="50" width="210" height="175" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">İspanya (Güney Avrupa / Akdeniz)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#334155">• Akdeniz iklimi ve neşeli yaşam</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#334155">• Endülüs mimari mirası</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#334155">• Meydan kültürü, sanat ve</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">canlı beden dili kullanımı</text>\n  <rect x="470" y="50" width="210" height="175" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Norveç (Kuzey Avrupa / Kutup)</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11" fill="#334155">• Fiyortlar, kar ve kuzey ışıkları</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#334155">• Gece yarısı güneşi / kış gecesi</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11" fill="#334155">• Doğa sporları, sakin iletişim</text>\n  <text x="575" y="160" text-anchor="middle" font-size="11" fill="#334155">ve kişisel alana saygı</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">EKLER: ÇEKİM EKLERİ VE YAPIM EKLERİ (T.O.6.5)</text>\n  <rect x="30" y="50" width="305" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yapım Ekleri (Anlam Değiştiren)</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#334155">• Sözcüğün anlamını veya türünü değiştirerek</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11" fill="#334155">yeni bir \'türemiş sözcük\' (gövde) oluşturur.</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Örnekler:</text>\n  <text x="182" y="166" text-anchor="middle" font-size="11" fill="#334155">gez-gin, yol-cu-luk, göz-lük, bil-gi-li, sev-gi</text>\n  <rect x="365" y="50" width="305" height="170" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Çekim Ekleri (Anlam Değiştirmeyen)</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#334155">• Sözcüğün anlamını değiştirmez; cümle içinde</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11" fill="#334155">diğer sözcüklerle bağ kurmasını sağlar.</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Örnekler:</text>\n  <text x="517" y="166" text-anchor="middle" font-size="11" fill="#334155">ülke-ler-i-miz-de (çoğul + iyelik + bulunma)</text>\n</svg>', '2': '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">EKLER: ÇEKİM EKLERİ VE YAPIM EKLERİ (T.O.6.5)</text>\n  <rect x="30" y="50" width="305" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yapım Ekleri (Anlam Değiştiren)</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#334155">• Sözcüğün anlamını veya türünü değiştirerek</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11" fill="#334155">yeni bir \'türemiş sözcük\' (gövde) oluşturur.</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Örnekler:</text>\n  <text x="182" y="166" text-anchor="middle" font-size="11" fill="#334155">gez-gin, yol-cu-luk, göz-lük, bil-gi-li, sev-gi</text>\n  <rect x="365" y="50" width="305" height="170" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Çekim Ekleri (Anlam Değiştirmeyen)</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#334155">• Sözcüğün anlamını değiştirmez; cümle içinde</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11" fill="#334155">diğer sözcüklerle bağ kurmasını sağlar.</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Örnekler:</text>\n  <text x="517" y="166" text-anchor="middle" font-size="11" fill="#334155">ülke-ler-i-miz-de (çoğul + iyelik + bulunma)</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YAPILARINA GÖRE SÖZCÜKLER: BASİT, TÜREMİŞ VE BİRLEŞİK SÖZCÜK</text>\n  <rect x="20" y="50" width="205" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="122" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Basit Sözcük</text>\n  <text x="122" y="102" text-anchor="middle" font-size="11" fill="#334155">Yapım eki almamış sözcüktür.</text>\n  <text x="122" y="120" text-anchor="middle" font-size="11" fill="#334155">(Çekim eki alabilir!)</text>\n  <text x="122" y="152" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Örnek: "deniz-ler-de",</text>\n  <text x="122" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">"çocuk-lar-ımız"</text>\n  <rect x="247" y="50" width="205" height="170" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Türemiş Sözcük</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#334155">En az bir yapım eki almış</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#334155">(gövde durumundaki) sözcüktür.</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Örnek: "deniz-ci-lik",</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">"ara-ştır-ma", "kültür-lü"</text>\n  <rect x="475" y="50" width="205" height="170" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="577" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Birleşik Sözcük</text>\n  <text x="577" y="102" text-anchor="middle" font-size="11" fill="#334155">En az iki sözcüğün yeni bir</text>\n  <text x="577" y="120" text-anchor="middle" font-size="11" fill="#334155">kavramı karşılamak üzere</text>\n  <text x="577" y="138" text-anchor="middle" font-size="11" fill="#334155">birleşmesiyle oluşur.</text>\n  <text x="577" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Örnek: "Akdeniz", "birtakım",</text>\n  <text x="577" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">"conk-bayırı", "yardım et-"</text>\n</svg>', '3': '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YAPILARINA GÖRE SÖZCÜKLER: BASİT, TÜREMİŞ VE BİRLEŞİK SÖZCÜK</text>\n  <rect x="20" y="50" width="205" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="122" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Basit Sözcük</text>\n  <text x="122" y="102" text-anchor="middle" font-size="11" fill="#334155">Yapım eki almamış sözcüktür.</text>\n  <text x="122" y="120" text-anchor="middle" font-size="11" fill="#334155">(Çekim eki alabilir!)</text>\n  <text x="122" y="152" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Örnek: "deniz-ler-de",</text>\n  <text x="122" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">"çocuk-lar-ımız"</text>\n  <rect x="247" y="50" width="205" height="170" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Türemiş Sözcük</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#334155">En az bir yapım eki almış</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#334155">(gövde durumundaki) sözcüktür.</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Örnek: "deniz-ci-lik",</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">"ara-ştır-ma", "kültür-lü"</text>\n  <rect x="475" y="50" width="205" height="170" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="577" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Birleşik Sözcük</text>\n  <text x="577" y="102" text-anchor="middle" font-size="11" fill="#334155">En az iki sözcüğün yeni bir</text>\n  <text x="577" y="120" text-anchor="middle" font-size="11" fill="#334155">kavramı karşılamak üzere</text>\n  <text x="577" y="138" text-anchor="middle" font-size="11" fill="#334155">birleşmesiyle oluşur.</text>\n  <text x="577" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Örnek: "Akdeniz", "birtakım",</text>\n  <text x="577" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">"conk-bayırı", "yardım et-"</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">EK HALİNDEKİ ZAMİRLER: İYELİK ZAMİRİ VE İLGİ ZAMİRİ (-ki)</text>\n  <rect x="30" y="52" width="305" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">İyelik (Aitlik) Zamirleri</text>\n  <text x="182" y="104" text-anchor="middle" font-size="11" fill="#334155">• İsimlere gelerek varlığın kime veya neye</text>\n  <text x="182" y="122" text-anchor="middle" font-size="11" fill="#334155">ait olduğunu belirten çekim ekleridir.</text>\n  <text x="182" y="148" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Örnek: kültür-üm, kültür-ün, kültür-ü,</text>\n  <text x="182" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">kültür-ümüz, kültür-ünüz, kültür-leri</text>\n  <rect x="365" y="52" width="305" height="165" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">İlgi Zamiri (-ki)</text>\n  <text x="517" y="104" text-anchor="middle" font-size="11" fill="#334155">• Cümlede daha önce geçen bir ismin yerini</text>\n  <text x="517" y="122" text-anchor="middle" font-size="11" fill="#334155">tutan ve \'-ınki / -inki\' biçiminde bitişik</text>\n  <text x="517" y="140" text-anchor="middle" font-size="11" fill="#334155">yazılan ektir.</text>\n  <text x="517" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Örnek: "Mısır\'ın iklimi sıcak, Norveç\'inki (=iklimi) soğuktur."</text>\n</svg>', '4': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">EK HALİNDEKİ ZAMİRLER: İYELİK ZAMİRİ VE İLGİ ZAMİRİ (-ki)</text>\n  <rect x="30" y="52" width="305" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">İyelik (Aitlik) Zamirleri</text>\n  <text x="182" y="104" text-anchor="middle" font-size="11" fill="#334155">• İsimlere gelerek varlığın kime veya neye</text>\n  <text x="182" y="122" text-anchor="middle" font-size="11" fill="#334155">ait olduğunu belirten çekim ekleridir.</text>\n  <text x="182" y="148" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Örnek: kültür-üm, kültür-ün, kültür-ü,</text>\n  <text x="182" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">kültür-ümüz, kültür-ünüz, kültür-leri</text>\n  <rect x="365" y="52" width="305" height="165" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">İlgi Zamiri (-ki)</text>\n  <text x="517" y="104" text-anchor="middle" font-size="11" fill="#334155">• Cümlede daha önce geçen bir ismin yerini</text>\n  <text x="517" y="122" text-anchor="middle" font-size="11" fill="#334155">tutan ve \'-ınki / -inki\' biçiminde bitişik</text>\n  <text x="517" y="140" text-anchor="middle" font-size="11" fill="#334155">yazılan ektir.</text>\n  <text x="517" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Örnek: "Mısır\'ın iklimi sıcak, Norveç\'inki (=iklimi) soğuktur."</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">GEZİ YAZISI (SEYAHATNAME) VE DÜŞÜNCEYİ GELİŞTİRME YOLLARI</text>\n  <rect x="25" y="52" width="310" height="165" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Gezi Yazısının Özellikleri</text>\n  <text x="180" y="104" text-anchor="middle" font-size="11" fill="#334155">• Gezilip görülen yerlerin doğal güzellikleri,</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#334155">tarihî eserleri ve halkın yaşam biçimi anlatılır.</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11" fill="#334155">• Gözlem gücü ve betimleyici anlatım öne çıkar.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#334155">• Okurda merak ve açık fikirlilik uyandırır.</text>\n  <rect x="365" y="52" width="310" height="165" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="520" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Düşünceyi Geliştirme Yolları</text>\n  <text x="520" y="104" text-anchor="middle" font-size="11" fill="#334155">• Karşılaştırma: İki ülkenin iklim ve kültür farkı</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#334155">• Örneklendirme: Yöresel yemek ve gelenek örnekleri</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" fill="#334155">• Sayısal Verilerden Yararlanma: Nüfus ve yüz ölçümü</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#334155">• Duyulardan Yararlanma: Renk, ses ve tat betimlemesi</text>\n</svg>', '5': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">GEZİ YAZISI (SEYAHATNAME) VE DÜŞÜNCEYİ GELİŞTİRME YOLLARI</text>\n  <rect x="25" y="52" width="310" height="165" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Gezi Yazısının Özellikleri</text>\n  <text x="180" y="104" text-anchor="middle" font-size="11" fill="#334155">• Gezilip görülen yerlerin doğal güzellikleri,</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#334155">tarihî eserleri ve halkın yaşam biçimi anlatılır.</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11" fill="#334155">• Gözlem gücü ve betimleyici anlatım öne çıkar.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#334155">• Okurda merak ve açık fikirlilik uyandırır.</text>\n  <rect x="365" y="52" width="310" height="165" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="520" y="76" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Düşünceyi Geliştirme Yolları</text>\n  <text x="520" y="104" text-anchor="middle" font-size="11" fill="#334155">• Karşılaştırma: İki ülkenin iklim ve kültür farkı</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#334155">• Örneklendirme: Yöresel yemek ve gelenek örnekleri</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" fill="#334155">• Sayısal Verilerden Yararlanma: Nüfus ve yüz ölçümü</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#334155">• Duyulardan Yararlanma: Renk, ses ve tat betimlemesi</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KİP VE ZAMİR KARŞITLIĞI İLE TDK YAZIM KURALLARI ("-ki"NİN YAZIMI)</text>\n  <rect x="20" y="52" width="210" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Bağlaç Olan "ki" (AYRI)</text>\n  <text x="125" y="104" text-anchor="middle" font-size="11" fill="#334155">Cümleleri birbirine bağlar,</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#334155">sözcükten ayrı yazılır.</text>\n  <text x="125" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">"Anladım ki her kültür bir hazinedir."</text>\n  <text x="125" y="168" text-anchor="middle" font-size="10.5" fill="#475569">(İstisna: SOMBAHÇEMî bitişik)</text>\n  <rect x="245" y="52" width="210" height="165" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">2. Sıfat Yapan "-ki" (BİTİŞİK)</text>\n  <text x="350" y="104" text-anchor="middle" font-size="11" fill="#334155">Yer ve zaman bildirerek</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#334155">önündeki ismi niteler (Yapım eki).</text>\n  <text x="350" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">"Gökyüzündeki kuzey ışıkları"</text>\n  <text x="350" y="168" text-anchor="middle" font-size="10.5" fill="#475569">"Akşamki belgesel"</text>\n  <rect x="470" y="52" width="210" height="165" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. İlgi Zamiri "-ki" (BİTİŞİK)</text>\n  <text x="575" y="104" text-anchor="middle" font-size="11" fill="#334155">Düşen bir ismin yerini tutar</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#334155">(Çekim eki / Ek zamir).</text>\n  <text x="575" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">"Bizim kültürümüz sıcak, onlarınki sakin."</text>\n  <text x="575" y="168" text-anchor="middle" font-size="10.5" fill="#475569">(onlarınki = onların kültürü)</text>\n</svg>', '6': '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KİP VE ZAMİR KARŞITLIĞI İLE TDK YAZIM KURALLARI ("-ki"NİN YAZIMI)</text>\n  <rect x="20" y="52" width="210" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Bağlaç Olan "ki" (AYRI)</text>\n  <text x="125" y="104" text-anchor="middle" font-size="11" fill="#334155">Cümleleri birbirine bağlar,</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#334155">sözcükten ayrı yazılır.</text>\n  <text x="125" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">"Anladım ki her kültür bir hazinedir."</text>\n  <text x="125" y="168" text-anchor="middle" font-size="10.5" fill="#475569">(İstisna: SOMBAHÇEMî bitişik)</text>\n  <rect x="245" y="52" width="210" height="165" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">2. Sıfat Yapan "-ki" (BİTİŞİK)</text>\n  <text x="350" y="104" text-anchor="middle" font-size="11" fill="#334155">Yer ve zaman bildirerek</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#334155">önündeki ismi niteler (Yapım eki).</text>\n  <text x="350" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">"Gökyüzündeki kuzey ışıkları"</text>\n  <text x="350" y="168" text-anchor="middle" font-size="10.5" fill="#475569">"Akşamki belgesel"</text>\n  <rect x="470" y="52" width="210" height="165" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. İlgi Zamiri "-ki" (BİTİŞİK)</text>\n  <text x="575" y="104" text-anchor="middle" font-size="11" fill="#334155">Düşen bir ismin yerini tutar</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#334155">(Çekim eki / Ek zamir).</text>\n  <text x="575" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">"Bizim kültürümüz sıcak, onlarınki sakin."</text>\n  <text x="575" y="168" text-anchor="middle" font-size="10.5" fill="#475569">(onlarınki = onların kültürü)</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
